CREATE OR REPLACE FUNCTION thf_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'registro inmutable: %', TG_TABLE_NAME; END $$;
CREATE TABLE IF NOT EXISTS schema_version (version BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE users ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('ADMIN','STAFF')), pw_hash TEXT NOT NULL, totp_secret TEXT, totp_enabled BIGINT NOT NULL DEFAULT 0, recovery_codes TEXT, failed_count BIGINT NOT NULL DEFAULT 0, locked_until TEXT, active BIGINT NOT NULL DEFAULT 1, created_at TEXT NOT NULL, last_login_at TEXT );
CREATE TABLE sessions ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, mfa_ok BIGINT NOT NULL DEFAULT 0, csrf TEXT NOT NULL, created_at TEXT NOT NULL, last_seen TEXT NOT NULL, expires_at TEXT NOT NULL, reauth_at TEXT, ip TEXT, ua TEXT );
CREATE TABLE audit_log ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, at TEXT NOT NULL, user_id BIGINT REFERENCES users(id), action TEXT NOT NULL, entity TEXT, entity_id TEXT, data TEXT, ip TEXT );
CREATE TABLE settings ( key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by BIGINT REFERENCES users(id) );
CREATE TABLE setting_revisions ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, key TEXT NOT NULL, old_value TEXT, new_value TEXT NOT NULL, user_id BIGINT REFERENCES users(id), reason TEXT, at TEXT NOT NULL );
CREATE TABLE exchange_rates ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, source TEXT NOT NULL DEFAULT 'BCV', bs_per_usd_milli BIGINT NOT NULL, set_at TEXT NOT NULL, user_id BIGINT REFERENCES users(id) );
CREATE TABLE media ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('image','video')), path TEXT NOT NULL UNIQUE, thumb_path TEXT, width BIGINT, height BIGINT, bytes BIGINT, alt TEXT NOT NULL DEFAULT '', title TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT '', uploaded_by BIGINT REFERENCES users(id), created_at TEXT NOT NULL );
CREATE TABLE collections ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, kicker TEXT NOT NULL DEFAULT '', tagline TEXT NOT NULL DEFAULT '', intro TEXT NOT NULL DEFAULT '', story TEXT NOT NULL DEFAULT '', audience TEXT NOT NULL DEFAULT '', theme TEXT NOT NULL DEFAULT 'arena', hero_media_id BIGINT REFERENCES media(id), card_media_id BIGINT REFERENCES media(id), group_by_place BIGINT NOT NULL DEFAULT 0, sort BIGINT NOT NULL DEFAULT 0, visible BIGINT NOT NULL DEFAULT 1, coming_soon BIGINT NOT NULL DEFAULT 0, seo_title TEXT NOT NULL DEFAULT '', seo_desc TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL );
CREATE TABLE categories ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, sort BIGINT NOT NULL DEFAULT 0 );
CREATE TABLE places ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, region TEXT NOT NULL DEFAULT '', direction TEXT NOT NULL CHECK (direction IN ('O','N','E','S')), title TEXT NOT NULL, subtitle TEXT NOT NULL DEFAULT '', story TEXT NOT NULL DEFAULT '', lon DOUBLE PRECISION NOT NULL, lat DOUBLE PRECISION NOT NULL, photo_media_id BIGINT REFERENCES media(id), sort BIGINT NOT NULL DEFAULT 0, visible BIGINT NOT NULL DEFAULT 1, direction_note TEXT NOT NULL DEFAULT '', map_pos TEXT NOT NULL DEFAULT 's' CHECK (map_pos IN ('n','s','e','w')) );
CREATE TABLE products ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, provisional_name BIGINT NOT NULL DEFAULT 0, collection_id BIGINT REFERENCES collections(id), category_id BIGINT REFERENCES categories(id), place_id BIGINT REFERENCES places(id), type TEXT NOT NULL DEFAULT '', stone TEXT NOT NULL DEFAULT '', material TEXT NOT NULL DEFAULT 'Cadena con baño de oro 18k', detail TEXT NOT NULL DEFAULT '', story TEXT NOT NULL DEFAULT '', care TEXT NOT NULL DEFAULT '', audience TEXT NOT NULL DEFAULT '', price_cents BIGINT NOT NULL CHECK (price_cents >= 0), offer_cents BIGINT CHECK (offer_cents IS NULL OR offer_cents >= 0), wholesale_cents BIGINT CHECK (wholesale_cents IS NULL OR wholesale_cents >= 0), cost_cents BIGINT, suggested_cents BIGINT, min_cents BIGINT, max_cents BIGINT, is_bundle BIGINT NOT NULL DEFAULT 0, bundle_pieces BIGINT, lead_min_days BIGINT NOT NULL DEFAULT 7, lead_max_days BIGINT NOT NULL DEFAULT 10, variants TEXT NOT NULL DEFAULT '["40 cm","45 cm","50 cm"]', sku TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'published' CHECK (status IN ('draft','published','archived')), featured BIGINT NOT NULL DEFAULT 0, inset_enabled BIGINT NOT NULL DEFAULT 0, inset_title TEXT NOT NULL DEFAULT '', inset_note TEXT NOT NULL DEFAULT '', in_catalog BIGINT NOT NULL DEFAULT 1, is_demo_price BIGINT NOT NULL DEFAULT 1, sort BIGINT NOT NULL DEFAULT 0, seo_title TEXT NOT NULL DEFAULT '', seo_desc TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE INDEX idx_products_collection ON products(collection_id);
