CREATE TABLE product_media ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE CASCADE, media_id BIGINT NOT NULL REFERENCES media(id), role TEXT NOT NULL DEFAULT 'gallery' CHECK (role IN ('main','hover','inset','gallery','model')), sort BIGINT NOT NULL DEFAULT 0 );
CREATE TABLE looks ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, subtitle TEXT NOT NULL DEFAULT '', story TEXT NOT NULL DEFAULT '', collection_id BIGINT REFERENCES collections(id), place_id BIGINT REFERENCES places(id), media_id BIGINT REFERENCES media(id), place_media_id BIGINT REFERENCES media(id), discount_bps BIGINT NOT NULL DEFAULT 1000, active BIGINT NOT NULL DEFAULT 1, sort BIGINT NOT NULL DEFAULT 0, updated_at TEXT NOT NULL );
CREATE TABLE look_items ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, look_id BIGINT NOT NULL REFERENCES looks(id) ON DELETE CASCADE, product_id BIGINT NOT NULL REFERENCES products(id), qty BIGINT NOT NULL DEFAULT 1 CHECK (qty BETWEEN 1 AND 20), x DOUBLE PRECISION NOT NULL DEFAULT 50, y DOUBLE PRECISION NOT NULL DEFAULT 50, sort BIGINT NOT NULL DEFAULT 0 );
CREATE TABLE shipping_zones ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('isla','retiro','nacional','internacional')), fee_cents BIGINT, free_over_cents BIGINT, allows_cod BIGINT NOT NULL DEFAULT 0, eta TEXT NOT NULL DEFAULT '', active BIGINT NOT NULL DEFAULT 1, sort BIGINT NOT NULL DEFAULT 0 );
CREATE TABLE shipping_states ( state TEXT PRIMARY KEY, zone_code TEXT NOT NULL DEFAULT 'nacional', eta TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', active BIGINT NOT NULL DEFAULT 1, sort BIGINT NOT NULL DEFAULT 0 );
CREATE TABLE payment_methods ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, currency TEXT NOT NULL DEFAULT 'USD', adj_bps BIGINT NOT NULL DEFAULT 0, island_only BIGINT NOT NULL DEFAULT 0, instructions TEXT NOT NULL DEFAULT '', active BIGINT NOT NULL DEFAULT 1, sort BIGINT NOT NULL DEFAULT 0 );
CREATE TABLE digital_products ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, subtitle TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', audience TEXT NOT NULL DEFAULT '', format TEXT NOT NULL DEFAULT 'PDF', pages BIGINT, price_cents BIGINT NOT NULL DEFAULT 0, cover_media_id BIGINT REFERENCES media(id), file_path TEXT, file_name TEXT, file_bytes BIGINT, file_sha256 TEXT, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','archived')), sort BIGINT NOT NULL DEFAULT 0, seo_title TEXT NOT NULL DEFAULT '', seo_desc TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL );
CREATE TABLE orders ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code TEXT NOT NULL UNIQUE, access_hash TEXT NOT NULL, idem_key TEXT UNIQUE, kind TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'creado', customer_name TEXT NOT NULL, customer_phone TEXT NOT NULL, customer_address TEXT NOT NULL DEFAULT '', customer_notes TEXT NOT NULL DEFAULT '', customer_email TEXT NOT NULL DEFAULT '', zone_code TEXT, zone_name TEXT, pay_code TEXT, pay_name TEXT, subtotal_cents BIGINT NOT NULL, shipping_cents BIGINT NOT NULL, adj_cents BIGINT NOT NULL, discount_cents BIGINT NOT NULL DEFAULT 0, total_cents BIGINT NOT NULL, shipping_label TEXT NOT NULL DEFAULT '', attribution_code TEXT, wa_message TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE order_lines ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK (kind IN ('product','look','digital')), ref_id BIGINT NOT NULL, name TEXT NOT NULL, sku TEXT NOT NULL DEFAULT '', variant TEXT NOT NULL DEFAULT '', qty BIGINT NOT NULL, unit_cents BIGINT NOT NULL, total_cents BIGINT NOT NULL, snapshot TEXT NOT NULL );
CREATE TABLE order_events ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, at TEXT NOT NULL, user_id BIGINT REFERENCES users(id), from_status TEXT, to_status TEXT, note TEXT );
