CREATE TABLE pages ( slug TEXT PRIMARY KEY, title TEXT NOT NULL, seo_title TEXT NOT NULL DEFAULT '', seo_desc TEXT NOT NULL DEFAULT '', heading TEXT NOT NULL DEFAULT '', intro TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '', faq TEXT NOT NULL DEFAULT '[]', og_media_id BIGINT REFERENCES media(id), updated_at TEXT NOT NULL );
